import itertools

def solve_game(initial_config):
    config = list(initial_config)
    turns = 0
    while True:
        k = sum(config)
        if k == 0:
            break
        # Flip the k-th coin. Note: k-th coin is index k-1.
        config[k-1] = 1 - config[k-1]
        turns += 1
    return turns

def average_turns(n):
    total_turns = 0
    total_configs = 2**n
    for config in itertools.product([0, 1], repeat=n):
        total_turns += solve_game(config)
    return total_turns / total_configs

for n in range(1, 11):
    print(f"n={n}, avg={average_turns(n)}")
